WITH gaps AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) > INTERVAL '14' DAY THEN 1 ELSE 0 END AS new_group_flag FROM web_events), sessions_web_events AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT s.id, s.session_id, s.event_type, s.page, s.event_time, s.island_id, (SELECT MIN(t2.duration_sec) FROM web_events t2 WHERE t2.session_id = s.session_id) AS min_web_event_duration_sec FROM sessions_web_events s ORDER BY min_web_event_duration_sec NULLS LAST;
